import { useState, useEffect } from "react";
import { db } from "../firebaseConfig";
import { ref, onValue } from "firebase/database";

const useRules = () => {
  const [rules, setRules] = useState([]);

  useEffect(() => {
    const rulesRef = ref(db, "/regler/0");

    const unsubscribe = onValue(rulesRef, (snapshot) => {
      const rawHTML = snapshot.val(); // Fetch the long string of HTML
      if (rawHTML) {
        const parser = new DOMParser();
        const doc = parser.parseFromString(rawHTML, "text/html"); // Parse the HTML
        const h2Elements = doc.querySelectorAll("h2"); // Select all <h2> elements
        const extractedRules = Array.from(h2Elements).map((el) => el.textContent); // Extract text content

        console.log("Extracted Rules:", extractedRules); // Log extracted rules
        setRules(extractedRules);
      } else {
        console.log("No data found in /regler/0"); // Log missing data
        setRules([]); // Handle empty or missing data
      }
    });

    return () => unsubscribe(); // Cleanup subscription on unmount
  }, []);

  // Log rules whenever they are updated
  useEffect(() => {
    console.log("Rules updated:", rules);
  }, [rules]);

  return rules;
};

export default useRules;
